import JSON
using SpecialFunctions

"""
	gen( domain, name )

Generate fixture data and write to file.

# Arguments

* `domain`: domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( Float32(0.5), stop = Float32(1.5), length = 3000 );
julia> gen( x, "data.json" );
```
"""
function gen( domain, name )
	x = collect( Float32.( domain ) );
	
	# Create a temporary JavaScript file to compute erfcinvf values
	temp_js_file = joinpath( dirname(@__FILE__), "temp_erfcinvf.js" )
	open(temp_js_file, "w") do io
		write(io, """
var erfcinvf = require('../../../lib');
var values = JSON.parse(process.argv[2]);
var results = values.map(function(val) {
	var result = erfcinvf(val);
	return result;
});
console.log(JSON.stringify(results));
""")
	end
	
	# Call JavaScript to get the correct erfcinvf values
	x_json = JSON.json(x)
	cmd = `node $(temp_js_file) $(x_json)`
	js_results = read(cmd, String)
	js_results = strip(js_results)
	
	# Parse the results and convert to Float32
	results = JSON.parse(js_results)
	y = Float32.(results)
	
	# Clean up temporary file
	rm(temp_js_file)

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# 0.5 <= x <= 1.5 (linear regime)
x = range( Float32(0.5), stop = Float32(1.5), length = 3000 );
gen( x, "x_0.5_1.5.json" );

# 0.25 < 2-x < 0.5
x = range( Float32(1.5), stop = Float32(1.75), length = 500 );
gen( x, "x_1.5_1.75.json" );

# 0.25 < x < 0.5
x = range( Float32(0.25), stop = Float32(0.5), length = 500 );
gen( x, "x_0.25_0.5.json" );

# 0.25 < 2-x < 0.00012340980408664937
x = range( Float32(1.75), stop = Float32(1.9998), length = 500 );
gen( x, "x_1.75_1.9998.json" );

# 0.00012340980408664937 < x < 0.25
x = range( Float32(0.0002), stop = Float32(0.25), length = 500 );
gen( x, "x_0.0002_0.25.json" );

# 0.00012340980408664937 < 2-x < 2.220446049250313e-16
x = range( Float32(1.9998), stop = Float32(1.99999994f0), length = 500 );
gen( x, "x_1.9998_1.9999..8.json" );

# 2.220446049250313e-16 < 2-x < 0
x = range( Float32(1.9999999f0), stop = Float32(1.99999994f0), length = 500 );
gen( x, "x_1.9999..8_2.json" );
